export async function request<T>(path: string, opts: { actor: string; method?: string; body?: unknown; signal?: AbortSignal; idempotencyKey?: string }): Promise<T> {
  const headers: Record<string,string> = { [ACTOR_HEADER]: opts.actor, Accept: "application/json" };
  if (opts.body !== undefined) headers["Content-Type"] = "application/json";
  if (opts.idempotencyKey) headers["Idempotency-Key"] = opts.idempotencyKey;
  const response = await fetch(path, { method: opts.method ?? "GET", headers, body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined, signal: opts.signal });
  if (!response.ok) {
    let code = "http_error", message = `Request failed (${response.status})`, details;
    try { const payload = await response.json(); code = payload.code ?? code; message = payload.message ?? message; details = payload.details; } catch { /* ignore */ }
    throw new ApiError(response.status, code, message, details);
  }
  return (await response.json()) as T;
}

